import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { gzipSync } from "node:zlib";
import { ROOT, computeCoverage, loadData } from "./lib/data.mjs";

const data = loadData();
const coverage = computeCoverage(data);
const pct = (n, total) => (total === 0 ? "n/a" : `${((n / total) * 100).toFixed(1)}%`);

const lines = [
  "# Coverage",
  "",
  "Generated by `npm run coverage`. Do not edit by hand.",
  "",
  `- Makes: **${coverage.makes}**`,
  `- Models: **${coverage.models}**`,
  "",
  "## Translations",
  "",
  "| Locale | Makes | Models |",
  "|---|---|---|",
];
for (const [code, c] of Object.entries(coverage.locales)) {
  lines.push(
    `| ${code} | ${c.translatedMakes}/${coverage.makes} (${pct(c.translatedMakes, coverage.makes)}) ` +
      `| ${c.translatedModels}/${coverage.models} (${pct(c.translatedModels, coverage.models)}) |`,
  );
}

for (const [code, c] of Object.entries(coverage.locales)) {
  lines.push("", `### Missing in \`${code}\` (falls back to canonical name)`, "");
  lines.push(
    `- Makes: ${c.missingMakes.length ? c.missingMakes.join(", ") : "none"}`,
    `- Models: ${c.missingModels.length ? c.missingModels.join(", ") : "none"}`,
  );
}

const sizeTargets = [
  "data/makes.json",
  "data/models.json",
  "locales/ar.json",
  "dist/index.js",
  "dist/index.cjs",
  "dist/locales/ar.js",
];
const sizeLines = [];
if (existsSync(join(ROOT, "dist"))) {
  sizeLines.push("", "## Sizes", "", "| File | Raw | Gzip |", "|---|---|---|");
  for (const file of sizeTargets) {
    const path = join(ROOT, file);
    if (!existsSync(path)) continue;
    const buf = readFileSync(path);
    const kb = (n) => `${(n / 1024).toFixed(1)} kB`;
    sizeLines.push(`| ${file} | ${kb(buf.length)} | ${kb(gzipSync(buf).length)} |`);
  }
}

const report = lines.join("\n") + "\n";
writeFileSync(join(ROOT, "docs", "COVERAGE.md"), report);
console.log(report + sizeLines.join("\n") + "\n");
